def transform(grid):
    H, W = len(grid), len(grid[0])
    bg = grid[0][0]
    nonbg = [(r, c) for r in range(H) for c in range(W) if grid[r][c] != bg]
    nbset = set(nonbg)
    markers, obj = [], []
    for (r, c) in nonbg:
        adj = any((rr, cc) in nbset and (rr, cc) != (r, c)
                  for rr in range(r-1, r+2) for cc in range(c-1, c+2)
                  if 0 <= rr < H and 0 <= cc < W)
        (markers if not adj else obj).append((r, c))
    r0 = min(r for r, c in obj); r1 = max(r for r, c in obj)
    c0 = min(c for r, c in obj); c1 = max(c for r, c in obj)
    pat = [[grid[r][c] for c in range(c0, c1+1)] for r in range(r0, r1+1)]
    ph, pw = len(pat), len(pat[0])
    dr, dc = ph // 2, pw // 2
    out = [row[:] for row in grid]
    for (r, c) in markers:
        tr, tc = r - dr, c - dc
        for i in range(ph):
            for j in range(pw):
                rr, cc = tr + i, tc + j
                if 0 <= rr < H and 0 <= cc < W and pat[i][j] != bg:
                    out[rr][cc] = pat[i][j]
    return out
